const loadedPhotos=new WeakSet(),loadingPhotos=new WeakSet();
const photoObserver=typeof IntersectionObserver==='function'?new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;photoObserver.unobserve(entry.target);const img=entry.target.querySelector('[data-photo]');if(img)void loadPhoto(img);}},{rootMargin:'160px'}):null;
async function loadPhoto(img){if(!img.isConnected||loadedPhotos.has(img)||loadingPhotos.has(img)||img.closest('details:not([open])'))return;loadingPhotos.add(img);try{const url=await attachmentURL(img.dataset.photo,img.closest('.attachment').dataset.attachmentTask);if(img.isConnected){if(url&&await imageType(url)){img.src=url;img.hidden=false;}else img.alt='PDF 材料';loadedPhotos.add(img);}}catch(e){if(img.isConnected)img.closest('.attachment').querySelector('.attachment-caption').textContent='附件读取失败，点击重试';}finally{loadingPhotos.delete(img);}}
function hydrateFiles(){photoObserver?.disconnect();if(s.view==='profile')void updateCacheUsage();for(const img of root.querySelectorAll('[data-photo]')){if(img.closest('details:not([open])')||loadedPhotos.has(img)||loadingPhotos.has(img))continue;if(photoObserver)photoObserver.observe(img.closest('.attachment'));else void loadPhoto(img);}}
async function updateCacheUsage(){const node=root.querySelector('[data-image-cache-size]');if(!node)return;const token=getToken(),bytes=await attachmentCacheBytes();if(!node.isConnected||token!==getToken())return;node.textContent=bytes>=1024**3?(bytes/1024**3).toFixed(2)+' GB':bytes>=1024**2?(bytes/1024**2).toFixed(1)+' MB':bytes>=1024?(bytes/1024).toFixed(1)+' KB':bytes+' B';}
window.addEventListener('image-cache-change',()=>{if(s.view==='profile')void updateCacheUsage();});
root.addEventListener('toggle',e=>{if(e.target instanceof HTMLDetailsElement&&e.target.open)void hydrateFiles();},true);
async function imageType(url){return (await fetch(url)).headers.get('content-type')?.startsWith('image/');}
async function openTask(id){const fromHistory=s.view==='risk'||(s.view==='task'&&s.taskReturnView==='risk');const task=await request(`/tasks/${encodeURIComponent(id)}`);s.task=task;s.taskReturnView=fromHistory?'risk':'tasks';if(fromHistory)s.task.phase='done';s.view='task';s.modal=null;}
async function reloadTaskForEditing(){
  const form=(root.querySelector('[role="dialog"] [data-action="reload-task"]')||root.querySelector('[data-action="reload-task"]'))?.closest('form');
  if(!form||!s.task)return;
  const formName=form.dataset.form,taskId=s.task.id,token=getToken(),phase=s.task.phase;
  const draft=[...form.elements].filter(input=>input.name&&input.type!=='file').map(input=>({name:input.name,type:input.type,value:input.value,checked:input.checked}));
  const savedForm=form.cloneNode(true);s.busy=true;root.setAttribute('aria-busy','true');
  try{
    const latest=await request(`/tasks/${encodeURIComponent(taskId)}`);
    if(!s.user||token!==getToken()||s.task?.id!==taskId)return;
    const stages={check:'进行中',issue:'进行中','review-issue':'待审核','finish-review':'待审核',material:'整改中',recheck:'整改中'};
    const issueId=s.modal?.issueId||s.modal?.record?.id;
    const issue=issueId?latest.issues.find(record=>record.id===issueId):null;
    let editable=latest.status===stages[formName];
    if(issueId)editable=editable&&!!issue&&(formName==='issue'?['待审核','已退回'].includes(issue.status):formName==='review-issue'?issue.status==='待审核':issue.status==='整改中');
    latest.phase=phase;s.task=latest;s.error='';
    if(s.modal?.record&&issue)s.modal.record=issue;
    render();
    let current=root.querySelector(`form[data-form="${formName}"]`);
    if(!current){const section=document.createElement('section');section.className='panel wide';section.innerHTML='<div class="panel-title"><h3>未提交内容</h3></div>';section.append(savedForm);root.querySelector('.main-content').append(section);current=savedForm;}
    for(const input of current.elements){if(!input.name||input.type==='file')continue;const value=draft.find(item=>item.name===input.name&&((input.type!=='checkbox'&&input.type!=='radio')||item.value===input.value));if(value){if(input.type==='checkbox'||input.type==='radio')input.checked=value.checked;else input.value=value.value;}}
    updateReviewFields();current.dataset.syncDirty='true';
    const error=current.querySelector('[data-error]');
    if(error){error.textContent=editable?'任务已更新，请核对后重新提交。':`当前任务已进入${latest.status}，填写内容已保留。`;error.hidden=false;}
    current.querySelectorAll('[data-action="reload-task"]').forEach(button=>button.remove());
    if(!editable)current.querySelectorAll('button[type="submit"]').forEach(button=>button.disabled=true);
  }catch(error){if(s.user)flash(error.message);}finally{s.busy=false;root.removeAttribute('aria-busy');}
}
async function closeModal(){const m=s.modal;s.modal=null;render();for(const f of m?.files||[])if(f.temporary)await request(`/files/${encodeURIComponent(f.id)}`,{method:'DELETE'}).catch(()=>{});}
initializeNativeApp(async()=>{
  if(s.busy)return true;
  if(isAttachmentPreviewOpen()){closeAttachmentPreview();return true;}
  if(s.modal){await closeModal();return true;}
  if(s.view==='task'){nav(s.taskReturnView||'tasks');return true;}
  if(s.view==='unit'){nav('units');return true;}
  if(s.user&&s.view!=='home'){nav('home');return true;}
  return false;
}).catch(()=>{});
