if(['remove-custom-check','delete-saved-check'].includes(a)&&!b.dataset.deleteConfirmed){b.dataset.deleteLabel=b.textContent;b.dataset.deleteConfirmed='true';b.textContent='确认';return;}
if(a==='remove-custom-check'){s.modal.customItems.splice(Number(b.dataset.customIndex),1);updateChecklistPicker();return;}
