if(a==='reload-checklist'){await reloadChecklistOptions();return;}
if(a==='task'){await run(()=>openTask(b.dataset.id),{refresh:false,message:''});return;}if(a==='unit'){await run(async()=>{s.unit=await request(`/units/${encodeURIComponent(b.dataset.id)}`);for(const key of Object.keys(unitPages))unitPages[key]=1;s.view='unit';},{refresh:false,message:''});return;}
